import{B as t,p as l,f as o,j as e,S as r,P as n}from"./index-DGN-DdrE.js";const i={background:{color:"#0b0907"},blocks:[{type:t.HeaderBlock,overtitle:"Для партнёров",title:"Партнёрам",description:"Спонсорские активности на дринкапах обеспечивают глубокое касание аудитории и формируют приятные ассоциации с брендами.",background:{color:"#0b0907"},theme:"dark",verticalOffset:"l"},{type:t.InfoBlock,theme:"dark",backgroundColor:"#1a1206",leftContent:{title:"Спонсорство дринкапа",text:"Благодаря дружественной атмосфере дринкапов спонсорские активности обеспечивают глубокое касание аудитории и формируют приятные ассоциации с брендами. Мы готовы к сотрудничеству в удобном для вас формате — финансовом (закрытие чека мероприятия) или нефинансовом (площадка, оборудование и т.д.).",list:[{title:"Активности с брендом",text:"Проведём совместные активности с упоминанием вашего бренда."},{title:"Спикеры",text:"Пригласим интересных спикеров из Москвы и других городов."},{title:"Места для сотрудников",text:"Зарезервируем места для ваших сотрудников."}],links:[{text:"Посмотреть мероприятия",url:"#/events"},{text:"Напишите организаторам",url:"#/?orgs"}]},rightContent:{title:"Кейс «Пивка для рывка»",text:"На дринкапе №4 мы опробовали спонсорский пакет поддержки мероприятия: на средства спонсоров организовали акцию — посетителей на баре ждало welcome-пиво.",links:[{text:"Страница дринкапа №4",url:"#/events/4453"}]}},{type:t.InfoBlock,theme:"dark",backgroundColor:"#1a1206",leftContent:{title:"Кто участники дринкапов",text:"Дринкапы собирают IT-специалистов всех направлений: разработчиков, деврелов, аналитиков, тестировщиков. Мероприятия закрытые — локация сообщается только подтверждённым участникам, поэтому аудитория своя и вовлечённая.",list:[{title:"До 100 человек в среднем",text:"Ограничены вместимостью площадки, а не количеством желающих."},{title:"~150 регистраций",text:"Подтверждаем участие по вместимости — 50–80 человек на дринкапе."},{title:"Экспертные доклады",text:"Спикеры — эксперты в своих областях с глубокими техническими докладами, поданными в неформальном формате."}],links:[{text:"Посмотреть мероприятия",url:"#/events"}]},rightContent:{title:"Почему это работает",text:"Формат афтепати × митапа даёт глубокое касание аудитории: участники слушают доклады и общаются в одном пространстве, без разделения на «сцену» и «после». Неформальная обстановка и близость по духу формируют приятные ассоциации с брендом."}},{type:t.CardLayoutBlock,title:"Отзывы партнёров",children:l},o]};function s(){return e.jsx(r,{children:e.jsx(n,{content:i})})}export{s as default};
